#include "instaham/cutter/OutlineBuilder.hpp"
#include "instaham/MaskUtils.hpp"
#include <opencv2/imgproc.hpp>
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace instaham {
static cv::Vec2d principal(const std::vector<cv::Point2d>&p){cv::Point2d m(0,0);for(auto&q:p)m+=q;m*=1.0/p.size();double sxx=0,syy=0,sxy=0;for(auto&q:p){double x=q.x-m.x,y=q.y-m.y;sxx+=x*x;syy+=y*y;sxy+=x*y;}double th=.5*atan2(2*sxy,sxx-syy);cv::Vec2d d(cos(th),sin(th));if(d[0]<0||(d[0]==0&&d[1]<0))d=-d;return unitVec(d);}
static std::vector<cv::Point2d> resample(const std::vector<cv::Point>&c,int n){if(c.size()<4)throw std::runtime_error("Contour too short");std::vector<cv::Point2d>cl;for(auto&p:c)cl.emplace_back(p.x,p.y);cl.push_back(cl.front());std::vector<double>cum(cl.size(),0);for(size_t i=1;i<cl.size();++i)cum[i]=cum[i-1]+cv::norm(cl[i]-cl[i-1]);double total=cum.back();if(!(total>0))throw std::runtime_error("Invalid contour perimeter");std::vector<cv::Point2d>o(n);size_t j=0;for(int i=0;i<n;i++){double t=total*i/n;while(j+1<cum.size()&&cum[j+1]<=t)j++;j=std::min(j,cl.size()-2);double den=cum[j+1]-cum[j],f=den<=1e-12?0:(t-cum[j])/den;o[i]=cl[j]*(1-f)+cl[j+1]*f;}return o;}
static std::vector<double> sgCoeffs(int w,int po){if(w%2==0)w++;int half=w/2;cv::Mat A(w,po+1,CV_64F);for(int i=0;i<w;i++){double z=i-half,v=1;for(int j=0;j<=po;j++){A.at<double>(i,j)=v;v*=z;}}cv::Mat pinv;cv::invert(A,pinv,cv::DECOMP_SVD);std::vector<double>c(w);for(int i=0;i<w;i++)c[i]=pinv.at<double>(0,i);return c;}
static std::vector<double> smooth1(const std::vector<double>&v,int window,int po){int n=v.size();if(window>=n)window=n%2==0?n-1:n-2;if(window%2==0)--window;if(window<=po)return v;auto c=sgCoeffs(window,po);int h=window/2;std::vector<double>o(n);for(int i=0;i<n;i++){double a=0;for(int k=0;k<window;k++)a+=c[k]*v[(i+k-h+n)%n];o[i]=a;}return o;}
OutlineResult buildOutline(const cv::Mat&mask,const OutlineConfig&cfg){auto c=largestExternalContour(mask,cv::CHAIN_APPROX_NONE);if(c.empty())throw std::runtime_error("No external contour");auto r=resample(c,cfg.resamplePoints);std::vector<double>x(r.size()),y(r.size());for(size_t i=0;i<r.size();i++){x[i]=r[i].x;y[i]=r[i].y;}x=smooth1(x,cfg.savgolWindow,cfg.savgolPolyorder);y=smooth1(y,cfg.savgolWindow,cfg.savgolPolyorder);OutlineResult o;o.mask=strictBinary(mask);o.smooth.resize(r.size());for(size_t i=0;i<r.size();i++)o.smooth[i]={x[i],y[i]};cv::Point2d centroid(0,0);for(auto&p:o.smooth)centroid+=p;centroid*=1.0/o.smooth.size();int hw=std::max(2,cfg.normalHalfWindow),n=o.smooth.size();o.normals.resize(n);for(int i=0;i<n;i++){std::vector<cv::Point2d>local;for(int d=-hw;d<=hw;d++)local.push_back(o.smooth[(i+d+n)%n]);auto t=principal(local);cv::Vec2d nn(-t[1],t[0]);cv::Vec2d tc(centroid.x-o.smooth[i].x,centroid.y-o.smooth[i].y);if(dot2(nn,tc)>0)nn=-nn;o.normals[i]=unitVec(nn);}return o;}
}
